// Independent generated archives for the staged Explorer entry point.
import assert from "node:assert/strict";
import { buildScriptFixtureZip, scriptFixtureSpecs } from "./tk3-script-interaction-fixtures.mjs";
import JSZip from "../../../vendor/jszip.min.js";
import { diagnosticPng } from "./companion-media-fixtures.mjs";
import { fixtures } from "./format-fixtures.mjs";

const z = value => Buffer.from(value + "\0", "ascii");
function ints(width, ...values) {
  const data = Buffer.alloc(width * values.length);
  values.forEach((value, index) => width === 2 ?
    data.writeInt16LE(value, index * width) : data.writeInt32LE(value, index * width));
  return data;
}
const short = (...values) => ints(2, ...values);
const long = (...values) => ints(4, ...values);
const pack = (...values) => Buffer.concat(values);

function replace(bytes, needle, value) {
  const data = Buffer.from(bytes);
  const offset = data.indexOf(needle);
  assert.ok(offset >= 0 && data.indexOf(needle, offset + 1) < 0,
    "Expected one fixture field: " + needle.toString("hex"));
  return pack(data.subarray(0, offset), value, data.subarray(offset + needle.length));
}

function zone(bytes, source) {
  const original = pack(z("doorTrigger.prg"), z("trigger.png"), z("doorClosed"), z("1"),
    z("doorOpen"), z("yes"), short(1,1,4,1,1), long(48,72,80,72), short(-1), z("door-trigger"));
  const replacement = pack(z(source), z(""), z(""), z(""), z(""), z(""),
    short(0,0,0,1,3), long(25,18,32,18,32,36,25,36), short(-1), z("gate"));
  return replace(bytes, original, replacement);
}

function addFight(zip, root, binary) {
  const background = binary ?
    pack(z("RPGTLKIT BKG"), short(2,3), z("field.png"), z("note.mid"), ...Array(4).fill(z(""))) :
    fixtures.find(fixture => fixture.path === "Bkrounds/room.bkg").bytes;
  const enemy = binary ?
    pack(z("RPGTLKIT ENEMY"), short(2,1), z("Synthetic Sentinel"), long(12,3,2,1),
      Buffer.from([1]), short(0,0,0), z(""), short(-1,-1), Buffer.from([0,0]),
      z(""), long(4,2), z("win.prg"), z(""), short(0), z("test_south.anm"), short(-1,0)) :
    Buffer.from(["RPGTLKIT ENEMY", 2, 0, "Synthetic Sentinel", 12, 3, 2, 1, 1, 0, 0,
      1, 1, ...Array(335).fill(""), 0, 0, "", 4, 2, "win.prg", "", "", "", "", "", ""
    ].join("\r\n"), "ascii");
  zip.file(root + "Enemy/sentinel.ene", enemy);
  zip.file(root + "Bkrounds/field.bkg", background);
  if (binary) {
    zip.file(root + "Bitmap/field.png", diagnosticPng);
    zip.file(root + "Media/note.mid", fixtures.find(f => f.path === "Media/note.mid").bytes);
    // One second of 8-bit PCM permits real pause/reset checks as well as
    // frame-triggered Web Audio. Dependent assets have generated bytes.
    const header = Buffer.from(fixtures.find(f => f.path === "Media/tone.wav").bytes.subarray(0, 44));
    const samples = Buffer.alloc(8000);
    for (let i = 0; i < samples.length; i++)
      samples[i] = 128 + Math.round(22 * Math.sin(i * Math.PI * 2 * 440 / 8000));
    header.writeUInt32LE(36 + samples.length, 4);
    header.writeUInt32LE(samples.length, 40);
    zip.file(root + "Media/tick.wav", pack(header, samples));
    zip.file(root + "Prg/media_probe.prg", [
      '// WAV and MIDI references use the native spelling',
      'wav("tick.wav")',
      'MediaPlay("note.mid")',
      'wav(sfxName)',
      'wav("unavailable.wav")',
      'wav("not-indexed.wav"',
    ].join("\n"));
  }
  zip.file(root + "Prg/win.prg", 'mwin("Sentinel defeated.")\nwait()\neraseItem("source")\nwon = 1');
}

const fight = 'mwin("The sentinel challenges you.")\nwait()\nmwinCls()\nfightEnemy("sentinel.ene", "field.bkg")';
export async function buildBrowserGame(id, options = {}) {
  const spec = scriptFixtureSpecs.find(spec => spec.id === id);
  const harbor = id === "harbor";
  const zip = await buildScriptFixtureZip({ ...spec, script: harbor ? "mwininn.prg" : spec.script,
    position: { x: 45, y: 27, layer: 1 } });
  const originalRoot = spec.root + "/";
  let gam = await zip.file(spec.main).async("nodebuffer");
  gam = replace(gam, z("gameover.prg"), z(harbor ? "" : "recover.prg"));
  if (options.blockStartup) zip.file(originalRoot + "Prg/" + spec.startup, "blocked = 1\nunsupportedAction(7)");
  if (harbor) {
    gam = replace(gam, pack(short(35), z("ENDDEMO.prg")), pack(short(101), z("station_report.prg")));
    gam = replace(gam, pack(short(29), z("menuMain.prg")), pack(short(98), z("broken.prg")));
    if (!options.blockStartup) zip.file(originalRoot + "Prg/" + spec.startup, "launched = 7\nclues = 3\nmaxclues = 9");
    zip.file(originalRoot + "Prg/station_report.prg",
      '#include("weather_clock.prg")\nReportTide()\ncaller_resumed = tide');
    zip.file(originalRoot + "Prg/weather_clock.prg",
      'method ReportTide()\n{\ntide = tide + 1\nmwin("The tide is rising.")\nwait()\nmwinCls()\n}');
    zip.file(originalRoot + "Prg/broken.prg", 'untouched = 1\n#include("broken_helper.prg")\nDecline()');
    zip.file(originalRoot + "Prg/broken_helper.prg", "method Decline()\n{\nunsupportedCommand(18)\n}");
    zip.file(originalRoot + "Prg/mwininn.prg",
      'mwin("Foreign archive dialogue.")\nwait()\nSend("missing.brd", 19, 27, 1)');
    const path = originalRoot + "Boards/" + spec.board;
    const onward = 'Send("beacon.brd", 19, 27, 2)';
    zip.file(path, zone(await zip.file(path).async("nodebuffer"),
      'send("channel.brd", 19, 27, 1)'));
    zip.file(originalRoot + "Boards/channel.brd", await zip.file(originalRoot + "Boards/beacon.brd").async("nodebuffer"));
    // Exercise a post-Send fight request from a file-backed GAM action.
    gam = replace(gam, pack(short(8), short(96), short(32)), pack(short(104), short(96), short(32)));
    zip.file(originalRoot + "Prg/runtime.prg", onward + '\nfightEnemy("sentinel.ene", "field.bkg")\narrived = 1');
    const beacon = originalRoot + "Boards/beacon.brd";
    const beaconBytes = await zip.file(beacon).async("nodebuffer");
    zip.file(beacon, replace(beaconBytes, short(0,1,78,45,1,-1), short(0,1,40,27,2,-1)));
    zip.file(originalRoot + "Prg/beacon_ending.prg", fight);
    addFight(zip, originalRoot, options.nativeEncounters ?? false);
    // A duplicate helper outside the GAM project must never be imported.
    zip.file("Foreign/Prg/" + spec.startup, "wrong = 1");
    zip.file("Foreign/Prg/sibling_only.prg", "wrong = 1");
    zip.file(originalRoot + "Prg/trace_probe.prg", '#Run("sibling_only.prg")');
    zip.file("Foreign/Prg/weather_clock.prg", "method ReportTide()\n{\nwrong = 1\n}");
    zip.file(originalRoot + "Foreign/Prg/mwininn.prg", 'mwin("Foreign decoy.")\nwait()');
    zip.file(originalRoot + "Main/" + spec.main, gam);
    zip.remove(spec.main);
  } else {
    gam = replace(gam, z(spec.startup), z(options.startupProgram ?? ""));
    gam = replace(gam, pack(short(8), short(96), short(32)), pack(short(116), short(96), short(32)));
    const path = originalRoot + "Boards/" + spec.board;
    const board = await zip.file(path).async("nodebuffer");
    const inherited = replace(board, z(spec.script), z(""));
    zip.file(path, inherited);
    const destination = replace(board, z(spec.script), z("challenge.prg"));
    zip.file(originalRoot + "Boards/ridge.brd", destination);
    zip.file(originalRoot + "Prg/pickup.prg", 'Send("ridge.brd", 19, 27, 1)\ntravelled = 1');
    zip.file(originalRoot + "Prg/challenge.prg", fight);
    zip.file(originalRoot + "Prg/runtime.prg",
      'Send("meadow.brd", 19, 27, 1)\nmwin("Return to the ridge?")\nwait()\nSend("ridge.brd", 19, 27, 1)');
    zip.file(originalRoot + "Prg/recover.prg", 'Send("meadow.brd", 19, 27, 1)\nmwin("Recover on the meadow.")\nwait()\nrecovered = 1');
    addFight(zip, originalRoot, true);
    // Flat project layout, independent of the nested Harbor GAM.
    for (const entry of Object.values(zip.files).filter(entry => !entry.dir && entry.name.startsWith(originalRoot))) {
      zip.file(entry.name.slice(originalRoot.length), await entry.async("uint8array"));
    }
    zip.remove(originalRoot);
    zip.file(spec.main, gam);
  }
  return zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE" });
}


// Two startup programs exercise the normal importer with different project
// layouts, include graphs, call nesting, conditions and source filenames.
export async function buildStartupExecutionGame(id) {
  const harbor = id === "harbor";
  const root = harbor ? "HarborLab/" : "";
  const startup = harbor ? "harbor_start.prg" : "morning.prg";
  const zip = await JSZip.loadAsync(await buildBrowserGame(id, { startupProgram: startup }));
  zip.file(root + "Prg/" + startup, harbor ? [
    '#include("arrival.prg")',
    "startup_runs = startup_runs + 1",
    "BeginArrival()",
    "startup_returned = 1",
  ].join("\n") : [
    "startup_runs = startup_runs + 1",
    '#include("orchard.prg")',
    "if (startup_runs == 1)",
    "{",
    "  GreetDay()",
    "}",
    "startup_returned = 1",
  ].join("\n"));
  if (harbor) {
    zip.file(root + "Prg/arrival.prg", [
      '#include("weather_clock.prg")',
      "method BeginArrival()",
      "{",
      "  ReportTide()",
      "  startup_ready = 1",
      "}",
    ].join("\n"));
    // The ordinary E key calls this exact helper again after startup.
  } else {
    zip.file("Prg/orchard.prg", [
      "method GreetDay()",
      "{",
      "  mwin(\"The orchard opens at dawn.\")",
      "  wait()",
      "  mwinCls()",
      "  startup_ready = 1",
      "}",
    ].join("\n"));
  }
  zip.file(root + "Prg/" + (harbor ? "mwininn.prg" : "pickup.prg"), [
    "if (startup_ready == 1)",
    "{",
    '  mwin("Startup prepared this object.")',
    "}",
    "else",
    "{",
    '  mwin("Startup was skipped.")',
    "}",
    "wait()",
    "talked = talked + 1",
  ].join("\n"));
  zip.file("Sibling/Prg/" + (harbor ? "arrival.prg" : "orchard.prg"),
    "method " + (harbor ? "BeginArrival" : "GreetDay") + "()\n{\nwrong = 1\n}");
  return zip;
}

// Authored independently of owner archives: different flow, names and layout.
export async function buildTitleExecutionGame(id) {
  const harbor = id === "harbor", root = harbor ? "HarborLab/" : "";
  const startup = harbor ? "harbor_start.prg" : "morning.prg";
  const zip = await buildStartupExecutionGame(id);
  const title = harbor ? "Harbor departure" : "Orchard morning";
  zip.file(root + "Media/note.mid", fixtures.find(f => f.path === "Media/note.mid").bytes);
  zip.file(root + "Media/tone.wav", fixtures.find(f => f.path === "Media/tone.wav").bytes);
  zip.file(root + "Bitmap/window.png", diagnosticPng);
  const helper = harbor ? "departure.prg" : "greeting.prg";
  zip.file(root + "Prg/" + helper, [
    'method Prepare(label, rounds) {',
    '  local(sum) = 0;',
    '  for(local(i)=0; i<rounds; i++) { local(sum) += i; }',
    '  startup_sum = sum;',
    // This library exceeds the retired 300-line ceiling with real work.
    ...Array(350).fill('  startup_checksum += 1;'),
    '  mwin(label + " ready"); wait(); mwinCls();',
    '  startup_ready = 1; return sum;',
    '}',
  ].join('\n'));
  const settings = 'fontSize(' + (harbor ? '18' : '22') + '); bold(true); winGraphic("window.png");\n';
  const sound = 'mediaPlay("' + (harbor ? 'note.mid' : 'tone.wav') + '");\n';
  const include = '#include "' + helper + '"\nstartup_runs += 1;\n';
  zip.file(root + "Prg/" + startup, include + settings + sound + (harbor ? [
    'while(true) {',
    '  clear(); text(3,3,"' + title + '");',
    '  text(10,8,"Depart"); text(10,10,"Inspect save"); text(10,12,"Leave");',
    '  cursor=createCursorMap(); cursorMapAdd(150,130,cursor); cursorMapAdd(150,170,cursor); cursorMapAdd(150,210,cursor);',
    '  choice=cursorMapRun(cursor); killCursorMap(cursor);',
    '  switch(choice) {',
    '    case(0) { result=Prepare("Harbor",4); startup_returned=1; end(); }',
    '    case(1) { load("unavailable.sav"); }',
    '    case(2) { windows(); }',
    '  }',
    '}',
  ] : [
    'for(attempt=0; !startup_ready; ++attempt) {',
    '  DrawHeading("' + title + '");',
    '  text(5,6,"Wake"); text(5,8,"Exit orchard");',
    '  menu=createCursorMap(); cursorMapAdd(60,110,menu); cursorMapAdd(60,154,menu);',
    '  action=cursorMapRun(menu); killCursorMap(menu);',
    '  if(action ~= 0) { windows(); } else { result=Prepare("Orchard",5); }',
    '}',
    'startup_returned=1;',
    'method DrawHeading(caption) { clear(); text(2,2,caption); }',
  ]).join('\n'));
  zip.file("Sibling/Prg/" + helper, "method Prepare(a,b) { wrong=1; }");
  return zip;
}

// Canvas programs share services with the player; their control flow is authored here.
export async function buildCanvasExecutionGame(id) {
  const harbor=id==='harbor',root=harbor?'HarborLab/':'';
  const zip=await buildTitleExecutionGame(id);
  zip.file(root+'Bitmap/chart.png',diagnosticPng);
  zip.file('Sibling/Bitmap/foreign-only.png',diagnosticPng);
  const helper=harbor?'scope.prg':'colors.prg';
  const script=[
    'method ReadColor(surface,x,y) {',
    '  getPixel(x,y,local(red),local(green),local(blue),surface);',
    '  return red+"-"+green+"-"+blue;',
    '}',
    'method ShowScope(label) {',
    '  local(panel)=createCanvas(640,480); createCanvas(640,480,local(mask));',
    '  colorRGB(34,56,78); fillRect(0,0,640,480,mask);',
    '  colorRGB(255,0,0); fillRect(0,0,40,40,mask);',
    '  setImage("chart.png",80,60,16,16,mask);',
    harbor?'  while(!KeyDown("ESC")) {':'  for(local(turn)=0; !KeyDown("ESC"); ++turn) {',
    '    clear(panel); colorRGB(8,16,24); fillRect(0,0,640,480,panel);',
    '    setImage("chart.png",480,100,128,128,panel);',
    '    setImageTransparent("chart.png",200,100,32,32,255,255,255,panel);',
    '    px=MouseStatus(0); py=MouseStatus(1); sample=ReadColor(mask,px,py);',
    '    colorRGB(255,255,255); pixelText(12,12,label,panel);',
    '    pixelText(12,40,px+"x"+py,panel); pixelText(12,68,sample,panel);',
    '    if(MouseStatus(2)){pixelText(12,96,"Pressed",panel);}',
    '    elseif(MouseStatus(3)){pixelText(12,96,"Secondary",panel);}',
    '    else{pixelText(12,96,"Released",panel);}',
    '    chord=KeyDown("A","B"); frames+=1; drawCanvas(panel,0,0);',
    '  }',
    '  killCanvas(panel); killCanvas(mask); canvas_done+=1;',
    '  mwin(label+" closed"); wait(); mwinCls();',
    '}',
  ].join('\n');
  zip.file(root+'Prg/'+helper,script);
  if(harbor)zip.file(root+'Prg/station_report.prg','#include "scope.prg"\nShowScope("Harbor scope"); caller_done=1;');
  else {
    const startup=root+'Prg/morning.prg';
    const source=await zip.file(startup).async('string');
    zip.file(startup,'#include "colors.prg"\n'+source.replace('startup_returned=1;',
      'ShowScope("Grove palette"); caller_done=1; startup_returned=1;'));
  }
  return zip;
}

// Familiar names are deliberately misleading data, never adapter eligibility.
export async function buildNeutralInspectionGame(id) {
  const harbor = id === 'harbor', root = harbor ? 'HarborLab/' : '';
  const zip = await buildStartupExecutionGame(id);
  const mainPath = harbor ? 'HarborLab/Main/HarborLab.gam' : 'GroveLab.gam';
  const oldStartup = harbor ? 'harbor_start.prg' : 'morning.prg';
  const startup = harbor ? 'menuTitle.prg' : 'start.prg';
  zip.file(mainPath, replace(await zip.file(mainPath).async('nodebuffer'), z(oldStartup), z(startup)));
  zip.remove(root + 'Prg/' + oldStartup);
  if (harbor) {
    let gam = await zip.file(mainPath).async('nodebuffer');
    gam = replace(gam, z('Harbor Message Lab'), z('BSTW'));
    gam = replace(gam, z('mira.tem'), z('bruce.tem'));
    zip.file(mainPath, gam);
    zip.file(root + 'Chrs/bruce.tem', replace(await zip.file(root + 'Chrs/mira.tem').async('nodebuffer'), z('Mira'), z('Bruce')));
    zip.remove(root + 'Chrs/mira.tem');
  }
  const helper = harbor ? 'CMwin.prg' : 'CCmap.prg';
  const interaction = harbor ? 'mwininn.prg' : 'menuMain.prg';
  const boardPath = root + 'Boards/' + (harbor ? 'wharf.brd' : 'meadow.brd');
  zip.file(boardPath, replace(await zip.file(boardPath).async('nodebuffer'), z('openDoor.prg'), z('')));
  if (!harbor) {
    const itemPath = 'Item/oakidol.itm';
    zip.file(itemPath, replace(await zip.file(itemPath).async('nodebuffer'), z('pickup.prg'), z(interaction)));
  }
  zip.file(root + 'Prg/' + helper, harbor ?
    'method Recount(value) { return value+3; }' :
    'method updateClues(delta) { clues+=delta; }');
  zip.file(root + 'Prg/' + startup, '#include "' + helper + '"\n' + (harbor ? [
    'checked[4]=6; clues=2;',
    'mwin("Harbor neutral startup"); wait(); mwinCls();',
    'startup_returned=1;',
  ] : [
    'for(local(turn)=0; turn<2; ++turn) { clues+=3; }',
    'checked[11]=8; maxclues=4;',
    'mwin("Grove neutral startup"); wait(); mwinCls();',
    'startup_returned=1;',
  ]).join('\n'));
  zip.file(root + 'Prg/' + interaction, [
    '// checked[0], clues++, updateClues("comment") are not commands here.',
    '#include "' + helper + '"',
    'literal="checked[99] clues++ updateClues(fake)";',
    harbor ? 'checked[4]+=1;' : 'checked[11]+=2;',
    harbor ? 'clues=Recount(clues);' : 'updateClues(2);',
    'mwin("' + (harbor ? 'Harbor' : 'Grove') + ' ordinary interaction");',
    'wait(); mwinCls();',
  ].join('\n'));
  zip.file(root + 'Prg/quest_only.prg', 'checked[0]=1; clues++;');
  zip.file(root + 'Prg/static_probe.prg', [
    '// Send("fake.brd",1,2); updateClues("comment");',
    'literal="checked[0] clues++ mediaPlay(fake.mid)";',
    'arbitraryMethod(17);',
    'unknownLibrary->Render("source evidence");',
    'mediaPlay("note.mid");',
    ...Array.from({length:14}, (_,i) => 'AnotherCall(' + i + ');'),
  ].join('\n'));
  zip.file(root + 'Media/note.mid', fixtures.find(f => f.path === 'Media/note.mid').bytes);
  zip.file(root + 'Prg/' + (harbor ? 'menuMain.prg' : 'mwininn.prg'), 'mwin("Unused familiar filename");');
  zip.file('Demo/Prg/start.prg', 'mwin("Foreign startup must not run");');
  return zip;
}

export async function buildBoardEntryGame(id) {
  const harbor=id==='harbor',root=harbor?'HarborLab/':'';
  const zip=await buildTitleExecutionGame(id);
  const opening=harbor?'wharf.brd':'meadow.brd', destination=harbor?'channel.brd':'ridge.brd';
  const entry=harbor?'harbor_entry.prg':'grove_entry.prg';
  for(const [name,script] of [[opening,entry],[destination,'destination_entry.prg']]) {
    const path=root+'Boards/'+name;
    zip.file(path,replace(await zip.file(path).async('nodebuffer'),z('arrival.prg'),z(script)));
  }
  zip.file(root+'Prg/'+entry,'entry_visits+=1; mwin("'+id+' entry "+entry_visits); wait(); mwinCls();');
  zip.file(root+'Prg/destination_entry.prg','destination_visits+=1; mwin("'+id+' destination entry"); wait(); mwinCls();');
  const send='before_send=entry_visits; Send("'+destination+'",19,27); after_entry=destination_visits; Send("'+opening+'",19,27); returned=entry_visits;';
  zip.file(root+'Prg/'+(harbor?'station_report.prg':'runtime.prg'),send);
  return zip;
}

export async function buildBackgroundGame(id) {
  const harbor=id==='harbor',root=harbor?'HarborLab/':'',zip=await buildBoardEntryGame(id);
  const boardPath=root+'Boards/'+(harbor?'wharf.brd':'meadow.brd');
  const worker=harbor?'weather_task.prg':'pulse_worker.prg';
  let board=await zip.file(boardPath).async('nodebuffer');
  board=replace(board,pack(short(0),z(''),short(1),z('alpha'),z('beta')),
    pack(short(0),z(worker),short(1),z('alpha'),z('beta')));
  if(harbor)board=replace(board,pack(z('dockbell.itm'),z('mwininn.prg'),z('')),
    pack(z('dockbell.itm'),z('mwininn.prg'),z('bell_motion.prg')));
  else {
    const path='Item/oakidol.itm';
    zip.file(path,replace(await zip.file(path).async('nodebuffer'),pack(z(''),z('pickup.prg')),pack(z('idle_worker.prg'),z('pickup.prg'))));
  }
  zip.file(boardPath,board);
  zip.file(root+'Prg/'+(harbor?'mwininn.prg':'pickup.prg'),'mwin("Worker interaction"); wait(); mwinCls(); talks+=1;');
  zip.file(root+'Prg/'+worker,'while(true) { board_ticks+=1; threadSleep(getThreadId(),0.05); }');
  zip.file(root+'Prg/'+(harbor?'bell_motion.prg':'idle_worker.prg'),'while(true) { item_ticks+=1; threadSleep(getThreadId(),0.08); }');
  zip.file(root+'Prg/bad_worker.prg','missingMethod();');
  zip.file(root+'Prg/spin_worker.prg','while(true){spins+=1;}');
  zip.file(root+'Prg/persistent_worker.prg','while(true) { persistent_ticks+=1; threadSleep(getThreadId(),0.04); }');
  const entry=root+'Prg/'+(harbor?'harbor_entry.prg':'grove_entry.prg');
  zip.file(entry,'if(persistent_id==0){persistent_id=thread("persistent_worker.prg",true);}\n'+await zip.file(entry).async('string'));
  return zip;
}

// Native ITM artwork and two independent authored movement/control flows.
export async function buildMovingGame(id) {
  const {nativeItem27}=await import('./native-item-27-fixtures.mjs');
  const harbor=id==='harbor',root=harbor?'HarborLab/':'',zip=await buildBackgroundGame(id);
  let item=replace(nativeItem27(),z('Synthetic Amulet'),z(harbor?'Harbor courier':'Grove walker'));
  for(const direction of ['south','north','east','west'])item=replace(item,z('native_'+direction+'.anm'),z('test_'+direction+'.anm'));
  item=replace(item,z('board.prg'),z(harbor?'':'idle_worker.prg'));
  zip.file(root+'Item/'+(harbor?'dockbell.itm':'oakidol.itm'),item);
  const main=root+(harbor?'Main/HarborLab.gam':'GroveLab.gam');
  zip.file(main,replace(await zip.file(main).async('nodebuffer'),pack(Buffer.from([1,2,3,4]),z('cursor.png')),pack(Buffer.from([1,2,3,1]),z('cursor.png'))));
  const opening=root+'Boards/'+(harbor?'wharf.brd':'meadow.brd');
  let board=replace(await zip.file(opening).async('nodebuffer'),long(2,3,68,3,32,45),long(90,0,95,0,95,64));
  board=replace(board,short(-4,1,-3,2,-5,1),short(-4,1,-2,2,-6,0));
  if(harbor)board=replace(board,z('send("channel.brd", 19, 27, 1)'),z(''));
  zip.file(opening,board);
  // Fixed 32px push mode in GAM is verified below by importer/unit tests.
  const worker=root+'Prg/'+(harbor?'bell_motion.prg':'idle_worker.prg');
  zip.file(worker,harbor ? [
    'itemSpeed("source",0.8);',
    'while(true){',
    '  pushItem("source","E",tkMV_PAUSE_THREAD);',
    '  itemLocation("source",npc_x,npc_y,npc_layer); item_ticks+=1;',
    '  threadSleep(getThreadId(),0.7);',
    '  pushItem("source","W",1); threadSleep(getThreadId(),0.7);',
    '}',
  ].join('\n') : [
    'itemSpeed("source",0.7);',
    'while(true){',
    '  pushItem("source","S",1);',
    '  itemLocation("source",npc_x,npc_y,npc_layer); item_ticks+=1;',
    '  threadSleep(getThreadId(),0.6);',
    '  pushItem("source","N",1); threadSleep(getThreadId(),0.6);',
    '}',
  ].join('\n'));
  zip.file(root+'Prg/'+(harbor?'mwininn.prg':'pickup.prg'),[
    'itemLocation("source",talk_x,talk_y,talk_layer);',
    'mwin("Moving worker at "+talk_x+","+talk_y); wait(); mwinCls(); talks+=1;',
  ].join('\n'));
  return zip;
}
